/**
 * Palette contrast verification.
 *
 * The light theme is generated by *inverting* each Tailwind ramp (50 <-> 950,
 * 500 fixed) rather than by hand-picking new values — see the note at the top of
 * tailwind.config.ts. That transform is mechanical, so the thing that actually
 * needs checking is whether the resulting steps clear WCAG at the roles the
 * codebase assigns them.
 *
 * This script resolves the real Tailwind theme (so it reads the same values the
 * build emits, not a copy of them) and reports the contrast ratio of every
 * text/surface pair the design system relies on. It fails the run if a pair used
 * for body text drops below 4.5:1 or a pair used for a UI boundary drops below
 * 3:1.
 *
 * Usage: node scripts/verify-palette-contrast.mjs
 */
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const resolveConfig = require("tailwindcss/resolveConfig");
const config = require("./load-tailwind-config.cjs");

const theme = resolveConfig(config).theme;

/** #rrggbb -> relative luminance (WCAG 2.x). */
function luminance(hex) {
  const raw = hex.replace("#", "");
  const full = raw.length === 3 ? [...raw].map((c) => c + c).join("") : raw;
  const [r, g, b] = [0, 2, 4].map((i) => {
    const channel = parseInt(full.slice(i, i + 2), 16) / 255;
    return channel <= 0.03928 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function ratio(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

/** #rrggbb over #rrggbb at alpha -> the composited #rrggbb. */
function over(fg, bg, alpha) {
  const parse = (hex) => [0, 2, 4].map((i) => parseInt(hex.replace("#", "").slice(i, i + 2), 16));
  const [r1, g1, b1] = parse(fg);
  const [r2, g2, b2] = parse(bg);
  return (
    "#" +
    [r1 * alpha + r2 * (1 - alpha), g1 * alpha + g2 * (1 - alpha), b1 * alpha + b2 * (1 - alpha)]
      .map((v) => Math.round(v).toString(16).padStart(2, "0"))
      .join("")
  );
}

/** Read a `family-step` path out of the resolved theme. */
function color(path) {
  const [family, step] = path.split(/-(?=[^-]*$)/);
  const scale = theme.colors[family] ?? theme.colors[path];
  if (typeof scale === "string") return scale;
  const value = scale?.[step] ?? scale?.DEFAULT;
  if (typeof value !== "string") throw new Error(`Unresolvable colour: ${path}`);
  return value;
}

const PAGE = "#ffffff";

/**
 * Tinted grounds, composited the way the browser does.
 *
 * This is the part a naive palette check misses. `.badge-brand` is
 * `bg-cyan/10 text-cyan` — a 10% fill of the mid step under brand-coloured text —
 * so the *ground* for that text is not the page. And because ~90 of those chips
 * sit inside panels that are themselves brand-tinted, the tint can apply twice.
 *
 * `audit-rendered-contrast.mjs` found the failures on the real DOM first; these
 * rows are how they stay fixed without a browser in the loop.
 */
const BRAND_TINT = over(color("cyan-500"), PAGE, 0.1);
const BRAND_TINT_DOUBLE = over(color("cyan-500"), BRAND_TINT, 0.1);
const NEUTRAL_TINT = over(color("slate-800"), PAGE, 0.6);
const SUCCESS_TINT = over(color("emerald-500"), PAGE, 0.1);
const WARNING_TINT = over(color("amber-500"), PAGE, 0.1);
const DANGER_TINT = over(color("rose-500"), PAGE, 0.1);
const INFO_TINT = over(color("sky-500"), PAGE, 0.1);

/**
 * Each row is a real role in the design system, with the minimum the role has
 * to meet. `text` roles are WCAG 1.4.3 (4.5:1); `ui` roles are 1.4.11 (3:1);
 * `large` roles are headings at >=24px semibold (3:1).
 */
const CHECKS = [
  // Text on the page / on a card. Both are #ffffff in this theme.
  ["heading  text-slate-100 on page", color("slate-100"), PAGE, 4.5, "text"],
  ["heading  text-slate-200 on page", color("slate-200"), PAGE, 4.5, "text"],
  ["body     text-slate-300 on page", color("slate-300"), PAGE, 4.5, "text"],
  ["muted    text-slate-400 on page", color("slate-400"), PAGE, 4.5, "text"],
  ["dimmest  text-slate-500 on page", color("slate-500"), PAGE, 4.5, "text"],

  // Brand. `text-cyan` is the legacy DEFAULT usage (links, active nav labels).
  // The numeric steps are checked too, because the ramp is mirrored: they are the
  // reason a naive port of this palette would have shipped 16 illegible links.
  ["link     text-cyan (DEFAULT)    ", color("cyan-DEFAULT"), PAGE, 4.5, "text"],
  ["link     text-cyan-300 on page  ", color("cyan-300"), PAGE, 4.5, "text"],
  ["link     text-cyan-400 on page  ", color("cyan-400"), PAGE, 4.5, "text"],
  // The logo's own #f96403, reachable as cyan-600 after the mirror. Graphic only.
  ["mark     cyan-600 as a graphic  ", color("cyan-600"), PAGE, 3.0, "ui"],

  // Primary action: white label on the brand fill.
  ["button   white on bg-cyan       ", "#ffffff", color("cyan-DEFAULT"), 4.5, "text"],
  // The logo hue as a *fill*, at 3.0 not 4.5. This row is the guardrail on the
  // rule stated in tailwind.config.ts: #f96403 clears 1.4.11 as a graphic and
  // lands at 3.06:1 against white, so a white label on it would be a 1.4.3
  // failure. If someone retunes the mark darker, this starts passing 4.5 and the
  // restriction can be lifted; if they retune it lighter, this fails and says so.
  ["mark     white on the logo hue  ", "#ffffff", color("cyan-600"), 3.0, "ui"],

  // Status text inside tinted badges. Tested against the *composited tint*, not
  // against white: `.badge-success` is `bg-emerald-500/10 text-emerald-300`, so
  // the ground is the tint. Testing against white overstates every one of these.
  ["badge    emerald on its tint     ", color("emerald-300"), SUCCESS_TINT, 4.5, "text"],
  ["badge    amber on its tint       ", color("amber-200"), WARNING_TINT, 4.5, "text"],
  ["badge    rose on its tint        ", color("rose-300"), DANGER_TINT, 4.5, "text"],
  ["badge    sky on its tint         ", color("sky-300"), INFO_TINT, 4.5, "text"],
  ["badge    neutral on its tint     ", color("slate-300"), NEUTRAL_TINT, 4.5, "text"],
  ["positive text-lime (DEFAULT)     ", color("lime-DEFAULT"), PAGE, 4.5, "text"],

  // The composition that actually broke: brand text on a brand chip, and the same
  // chip nested inside a brand-tinted panel so the tint applies twice.
  ["chip     brand on brand tint     ", color("cyan-DEFAULT"), BRAND_TINT, 4.5, "text"],
  ["chip     brand on doubled tint   ", color("cyan-DEFAULT"), BRAND_TINT_DOUBLE, 4.5, "text"],
  ["chip     dim text on brand tint  ", color("slate-500"), BRAND_TINT, 4.5, "text"],
  ["chip     dim text on neutral tint", color("slate-500"), NEUTRAL_TINT, 4.5, "text"],

  /** Self-tint: the same token used for the text and for the 10% fill under it.
   *  `.badge-success`, `.badge-brand`, and ~90 chip call sites do exactly this, and
   *  it is where the 700 steps failed. */
  ["chip     emerald on own tint     ", color("emerald-300"), over(color("emerald-300"), PAGE, 0.1), 4.5, "text"],
  ["chip     amber on own tint       ", color("amber-300"), over(color("amber-300"), PAGE, 0.1), 4.5, "text"],
  ["chip     lime on own tint        ", color("lime-DEFAULT"), over(color("lime-DEFAULT"), PAGE, 0.1), 4.5, "text"],
  ["chip     brand on own tint       ", color("cyan-DEFAULT"), over(color("cyan-DEFAULT"), PAGE, 0.1), 4.5, "text"],

  // Boundaries. A hairline between two cards is decorative (the card also has a
  // shadow), but a form field's border is the only thing announcing the field.
  ["control  .input border on page  ", "#64748b", PAGE, 3.0, "ui"],
  ["control  secondary btn border   ", color("slate-600"), PAGE, 3.0, "ui"],
  ["focus    ring on page           ", color("cyan-DEFAULT"), PAGE, 3.0, "ui"],
  ["focus    ring on sunken well    ", color("cyan-DEFAULT"), color("slate-950"), 3.0, "ui"],
];

let failures = 0;
console.log("role                                fg        bg        ratio   min   result");
console.log("-".repeat(78));

for (const [label, fg, bg, min, kind] of CHECKS) {
  const value = ratio(fg, bg);
  const ok = value >= min;
  if (!ok) failures += 1;
  console.log(
    `${label.padEnd(34)}  ${fg.padEnd(8)}  ${bg.padEnd(8)}  ${value.toFixed(2).padStart(5)}:1  ${min.toFixed(1)}  ${ok ? "pass" : "FAIL"} (${kind})`,
  );
}

console.log("-".repeat(78));
if (failures > 0) {
  console.log(`${failures} pair(s) below the required ratio.`);
  process.exitCode = 1;
} else {
  console.log("All design-system colour pairs meet WCAG AA for their role.");
}
